def _replay_exception(exc_class, exc_args):
    """按缓存的类与 args 重建异常，不调用其构造器。

    配置非法可能抛 json.JSONDecodeError（ValueError 子类），其构造签名与
    args 不同，直接 cls(*args) 会再抛 TypeError；经 __new__ 建实例并回填
    args 可原样重放任意异常类型。
    """
    exc = exc_class.__new__(exc_class)
    exc.args = exc_args
    return exc

